    "Marketing / Truyền thông": [
      "Tất cả vị trí",
      "Digital Marketing",
      "Content Marketing",
    ],
    "Chăm sóc khách hàng": ["Tất cả vị trí"],
    "Nhân sự / Hành chính": ["Tất cả vị trí"],
    "Tài chính / Ngân hàng": ["Tất cả vị trí"],
    "Bất động sản": ["Tất cả vị trí"],
